/* Simple design system */
:root {
    --primary-color: #0066ff; /* simple blue */
    --bg-color: #ffffff;
    --text-color: #212121;
    --font-primary: 'Roboto', sans-serif;
    --spacing: 1rem;
    --border-radius: 4px;
    --transition: 0.2s;
}

* {box-sizing:border-box; margin:0; padding:0;}
body {font-family: var(--font-primary); background: var(--bg-color); color: var(--text-color); line-height:1.5;}
.container {max-width:1200px; margin:auto; padding: var(--spacing);}
header {background: var(--primary-color); color:#fff; padding: var(--spacing);}
nav {display:flex; justify-content:space-between; align-items:center;}
nav a {color:#fff; text-decoration:none; margin:0 var(--spacing);}
nav a:hover {opacity:0.8;}
.btn {display:inline-block; background:var(--primary-color); color:#fff; padding:0.5rem 1rem; border:none; border-radius:var(--border-radius); cursor:pointer; text-decoration:none; transition:var(--transition);} 
.btn:hover {background:#0052cc;}
.grid {display:grid; grid-template-columns:repeat(auto-fit, minmax(200px,1fr)); gap:var(--spacing);}
.card {border:1px solid #ddd; border-radius:var(--border-radius); padding:var(--spacing); background:#fafafa;}
.card img {max-width:100%; height:auto; border-radius:var(--border-radius);}
.footer {background:#f2f2f2; text-align:center; padding:var(--spacing); margin-top:var(--spacing);}
@media(max-width:600px){nav{flex-direction:column;}}

// storage.js – simple wrapper for LocalStorage and initial seed data
(function(){
    const STORAGE_KEYS = {
        users: 'ecom_users',
        categories: 'ecom_categories',
        products: 'ecom_products',
        orders: 'ecom_orders',
        reviews: 'ecom_reviews',
        cart: 'ecom_cart', // will be stored per-customer: ecom_cart_<userId>
    };

    // --- Helper: get parsed JSON or fallback ---
    function get(key){
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : null;
    }
    function set(key, value){
        localStorage.setItem(key, JSON.stringify(value));
    }

    // --- Seed data – runs only on first load ---
    function seed(){
        if(!get(STORAGE_KEYS.users)){
            const demoUsers = [
                {id: 'u-admin', role:'admin', name:'Admin', email:'admin@shopdemo.com', password:'Admin@123'},
                {id: 'u-seller', role:'seller', name:'Seller', email:'seller@shopdemo.com', password:'Seller@123'},
                {id: 'u-customer', role:'customer', name:'Customer', email:'customer@shopdemo.com', password:'Customer@123'}
            ];
            set(STORAGE_KEYS.users, demoUsers);
        }
        if(!get(STORAGE_KEYS.categories)){
            const cats = [
                {id:'c-1', name:'Electronics'},
                {id:'c-2', name:'Fashion'},
                {id:'c-3', name:'Home & Kitchen'}
            ];
            set(STORAGE_KEYS.categories, cats);
        }
        if(!get(STORAGE_KEYS.products)){
            const products = [
                {id:'p-1', sellerId:'u-seller', categoryId:'c-1', name:'Simple Speaker', description:'A small Bluetooth speaker.', price:29.99, stock:15, image:'assets/images/speaker.jpg', rating:4.2, reviewCount:3, status:'approved', createdAt:new Date().toISOString()},
                {id:'p-2', sellerId:'u-seller', categoryId:'c-2', name:'Cotton T‑Shirt', description:'Comfortable unisex tee.', price:19.99, stock:30, image:'assets/images/tshirt.jpg', rating:4.5, reviewCount:5, status:'approved', createdAt:new Date().toISOString()},
                {id:'p-3', sellerId:'u-seller', categoryId:'c-3', name:'Ceramic Mug', description:'12 oz coffee mug.', price:9.99, stock:0, image:'assets/images/mug.jpg', rating:0, reviewCount:0, status:'out_of_stock', createdAt:new Date().toISOString()},
                // pending product example for seller demo
                {id:'p-4', sellerId:'u-seller', categoryId:'c-1', name:'Wireless Mouse', description:'Ergonomic mouse.', price:24.99, stock:20, image:'assets/images/mouse.jpg', rating:0, reviewCount:0, status:'pending', createdAt:new Date().toISOString()},
            ];
            set(STORAGE_KEYS.products, products);
        }
        if(!get(STORAGE_KEYS.orders)) set(STORAGE_KEYS.orders, []);
        if(!get(STORAGE_KEYS.reviews)) set(STORAGE_KEYS.reviews, []);
    }

    // Expose a simple API on window.StorageAPI
    window.StorageAPI = {
        keys: STORAGE_KEYS,
        get,
        set,
        seed,
        // utility to fetch user by email
        findUserByEmail(email){
            const users = get(STORAGE_KEYS.users) || [];
            return users.find(u => u.email===email);
        },
        // utility to get current logged‑in user (session stored under "ecom_session")
        getSession(){
            const raw = localStorage.getItem('ecom_session');
            return raw ? JSON.parse(raw) : null;
        },
        setSession(session){
            localStorage.setItem('ecom_session', JSON.stringify(session));
        },
        clearSession(){
            localStorage.removeItem('ecom_session');
        },
        // cart helpers – cart is stored per‑customer id
        getCart(userId){
            if(!userId) return [];
            return get('ecom_cart_' + userId) || [];
        },
        setCart(userId, cart){
            if(userId) set('ecom_cart_' + userId, cart);
        }
    };

    // Run seed on script load
    seed();
})();

// main.js – builds navigation bar and common UI helpers
(function(){
    // Build nav items based on role
    function buildNav(){
        const nav = document.getElementById('navbar');
        if(!nav) return;
        const session = window.StorageAPI.getSession();
        const links = [];
        // Common links
        links.push({href:'index.html', text:'Home'});
        links.push({href:'products.html', text:'Shop'});
        links.push({href:'about.html', text:'About'});
        links.push({href:'contact.html', text:'Contact'});
        if(!session){
            links.push({href:'login.html', text:'Login'});
            links.push({href:'register.html', text:'Register'});
        } else {
            if(session.role==='admin'){
                links.push({href:'admin/dashboard.html', text:'Admin'});
            } else if(session.role==='seller'){
                links.push({href:'seller/dashboard.html', text:'Seller'});
            } else if(session.role==='customer'){
                links.push({href:'customer/dashboard.html', text:'My Account'});
                links.push({href:'customer/cart.html', text:'Cart'});
            }
            links.push({href:'#', text:'Logout', onClick: logout});
        }
        // Render
        nav.innerHTML = '';
        links.forEach(l=>{
            const a = document.createElement('a');
            a.href = l.href;
            a.textContent = l.text;
            if(l.onClick){ a.addEventListener('click', function(e){ e.preventDefault(); l.onClick();}); }
            nav.appendChild(a);
        });
    }

    function logout(){
        window.StorageAPI.clearSession();
        // simple toast message
        alert('Logged out');
        buildNav();
        // redirect to home after short delay
        setTimeout(()=>{window.location.href='index.html';},500);
    }

    // expose for other scripts
    window.CommonUI = {buildNav, logout};

    // auto-run on load
    document.addEventListener('DOMContentLoaded', buildNav);
})();

// auth.js – login, register, session handling
(function(){
    const storage = window.StorageAPI;
    const sessionKey = 'ecom_session';

    // Helper: hash password (simple base64 for demo, NOT secure)
    function simpleHash(pwd){
        return btoa(pwd);
    }

    // Register new user (role = customer or seller)
    function register({name,email,password,role}){
        const users = storage.get(storage.keys.users) || [];
        if(users.some(u=>u.email===email)){
            alert('Email already exists');
            return false;
        }
        const newUser = {
            id: 'u-' + crypto.randomUUID(),
            name,
            email,
            password: simpleHash(password),
            role,
        };
        users.push(newUser);
        storage.set(storage.keys.users, users);
        alert('Registration successful. You can now log in.');
        window.location.href = 'login.html';
        return true;
    }

    // Login – verifies email/password
    function login(email,password){
        const users = storage.get(storage.keys.users) || [];
        const user = users.find(u=>u.email===email);
        if(!user){ alert('No account found'); return false; }
        if(user.password !== simpleHash(password)){
            alert('Incorrect password');
            return false;
        }
        const session = {userId:user.id, role:user.role, name:user.name, email:user.email};
        storage.setSession(session);
        // redirect based on role
        if(user.role==='admin') window.location.href='admin/dashboard.html';
        else if(user.role==='seller') window.location.href='seller/dashboard.html';
        else window.location.href='customer/dashboard.html';
        return true;
    }

    // Helper to enforce role on a page
    function requireRole(allowedRoles){
        const sess = storage.getSession();
        if(!sess || !allowedRoles.includes(sess.role)){
            alert('Access denied. Please log in with appropriate account.');
            window.location.href='login.html';
            return false;
        }
        return true;
    }

    // expose API
    window.Auth = {register, login, requireRole, getSession:()=>storage.getSession()};
})();
